int parse_mixer_config(const cJSON *obj, const char *ctx, mixer_config_t *out, config_error_t *err) {
  if (!cJSON_IsObject(obj)) {
    config_error_set(err, CONFIG_ERR_PARSE, "%s must be an object", ctx ? ctx : "mixer_config");
    return -1;
  }
  mixer_config_init(out);

  static const char *const allowed_keys[] = {"description", "mapping", "labels", "channels", NULL};
  if (validate_unknown_fields(obj, allowed_keys, ctx ? ctx : "mixer_config", err) != 0) return -1;

  static const char *const req_keys[] = {"mapping", NULL};
  if (require_json_fields(obj, req_keys, ctx ? ctx : "mixer_config", NULL, err) != 0) return -1;

  if (parse_json_str_strict(obj, "description", ctx ? ctx : "mixer_config", out->description, sizeof(out->description), NULL, err) != 0) return -1;
  cJSON *arr_mapping = cJSON_GetObjectItemCaseSensitive(obj, "mapping");
  if (arr_mapping) {
    if (!cJSON_IsArray(arr_mapping)) {
      config_error_set(err, CONFIG_ERR_PARSE, "field '%s' in %s must be an array", "mapping", ctx ? ctx : "mixer_config");
      return -1;
    }
    int count = cJSON_GetArraySize(arr_mapping);
    if (count > 0) {
      out->mapping = (mixer_mapping_t *)calloc(count, sizeof(mixer_mapping_t));
      if (!out->mapping) { config_error_set(err, CONFIG_ERR_PARSE, "Memory allocation failure"); return -1; }
      out->mapping_count = count;
      for (int i = 0; i < count; i++) {
        cJSON *item = cJSON_GetArrayItem(arr_mapping, i);
        if (parse_mixer_mapping(item, "mixer_mapping item", &out->mapping[i], err) != 0) return -1;
      }
    }
  }
  cJSON *arr_labels = cJSON_GetObjectItemCaseSensitive(obj, "labels");
  if (arr_labels) {
    if (parse_labels_array_strict(arr_labels, &out->labels, &out->labels_count, &out->has_labels) != 0) {
      config_error_set(err, CONFIG_ERR_PARSE, "field '%s' in %s must be an array of strings", "labels", ctx ? ctx : "mixer_config");
      return -1;
    }
  }
  cJSON *channels_obj = cJSON_GetObjectItemCaseSensitive(obj, "channels");
  if (!channels_obj || !cJSON_IsObject(channels_obj)) {
    config_error_set(err, CONFIG_ERR_PARSE, "missing or invalid required field 'channels' in %s", ctx ? ctx : "mixer_config");
    return -1;
  }
  static const char *const allowed_channels_keys[] = {"in", "out", NULL};
  if (validate_unknown_fields(channels_obj, allowed_channels_keys, "mixer_config channels", err) != 0) return -1;
  static const char *const req_channels[] = {"in", "out", NULL};
  if (require_json_fields(channels_obj, req_channels, "mixer_config channels", NULL, err) != 0) return -1;
  if (parse_json_size_t_strict(channels_obj, "in", "mixer_config channels", &out->channels_in, NULL, err) != 0) return -1;
  if (parse_json_size_t_strict(channels_obj, "out", "mixer_config channels", &out->channels_out, NULL, err) != 0) return -1;
  return 0;
}

cJSON *serialize_mixer_config(const mixer_config_t *in) {
  if (!in) return NULL;
  cJSON *obj = cJSON_CreateObject();
  if (!obj) return NULL;
  if (1) if (in->description[0]) cJSON_AddStringToObject(obj, "description", in->description);
  if (in->mapping && in->mapping_count > 0) {
    cJSON *arr = cJSON_CreateArray();
    for (size_t i = 0; i < in->mapping_count; i++) {
      cJSON_AddItemToArray(arr, serialize_mixer_mapping(&in->mapping[i]));
    }
    cJSON_AddItemToObject(obj, "mapping", arr);
  }
  if (in->labels && in->labels_count > 0) {
    cJSON *arr = cJSON_CreateArray();
    for (size_t i = 0; i < in->labels_count; i++) {
      if (in->labels[i]) cJSON_AddItemToArray(arr, cJSON_CreateString(in->labels[i]));
      else cJSON_AddItemToArray(arr, cJSON_CreateNull());
    }
    cJSON_AddItemToObject(obj, "labels", arr);
  }
  cJSON *channels_obj = cJSON_CreateObject();
  if (1) cJSON_AddNumberToObject(channels_obj, "in", (double)in->channels_in);
  if (1) cJSON_AddNumberToObject(channels_obj, "out", (double)in->channels_out);
  cJSON_AddItemToObject(obj, "channels", channels_obj);
  return obj;
}

bool mixer_config_equal(const mixer_config_t *a, const mixer_config_t *b) {
  if (a == b) return true;
  if (!a || !b) return false;
  if (strncmp(a->description, b->description, sizeof(a->description)) != 0) return false;
  if (a->channels_in != b->channels_in) return false;
  if (a->channels_out != b->channels_out) return false;
  if (a->mapping_count != b->mapping_count) return false;
  if (a->mapping_count > 0) {
    if (!a->mapping || !b->mapping) return false;
    for (size_t i = 0; i < a->mapping_count; i++) {
      if (!mixer_mapping_equal(&a->mapping[i], &b->mapping[i])) return false;
    }
  }
  if (a->has_labels != b->has_labels) return false;
  if (a->has_labels) {
    if (a->labels_count != b->labels_count) return false;
    if (a->labels_count > 0) {
      if (!a->labels || !b->labels) return false;
      for (size_t i = 0; i < a->labels_count; i++) {
        if ((a->labels[i] == NULL) != (b->labels[i] == NULL)) return false;
        if (a->labels[i] && strcmp(a->labels[i], b->labels[i]) != 0) return false;
      }
    }
  }
  return true;
}


