void biquad_combo_config_init(biquad_combo_config_t *out) {
  if (!out) return;
  memset(out, 0, sizeof(biquad_combo_config_t));
}

void free_biquad_combo_config_contents(biquad_combo_config_t *in) {
  if (!in) return;
  if (in->bands) {
    for (size_t i = 0; i < in->bands_count; i++) { free_peq_band_contents(&in->bands[i]); }
    free(in->bands);
    in->bands = NULL;
    in->bands_count = 0;
  }
  if (in->gains) { free(in->gains); in->gains = NULL; in->gains_count = 0; }
}

int parse_biquad_combo_config(const cJSON *obj, const char *ctx, biquad_combo_config_t *out, config_error_t *err) {
  if (!cJSON_IsObject(obj)) {
    config_error_set(err, CONFIG_ERR_PARSE, "%s must be an object", ctx ? ctx : "biquad_combo_config");
    return -1;
  }
  biquad_combo_config_init(out);

  static const config_enum_variant_t biquad_combo_config_type_variants[] = {
    {"ButterworthHighpass", BIQUAD_COMBO_TYPE_BUTTERWORTH_HIGHPASS},
    {"ButterworthLowpass", BIQUAD_COMBO_TYPE_BUTTERWORTH_LOWPASS},
    {"LinkwitzRileyHighpass", BIQUAD_COMBO_TYPE_LINKWITZ_RILEY_HIGHPASS},
    {"LinkwitzRileyLowpass", BIQUAD_COMBO_TYPE_LINKWITZ_RILEY_LOWPASS},
    {"Tilt", BIQUAD_COMBO_TYPE_TILT},
    {"NPointPeq", BIQUAD_COMBO_TYPE_N_POINT_PEQ},
    {"GraphicEqualizer", BIQUAD_COMBO_TYPE_GRAPHIC_EQUALIZER},
    {NULL, 0}
  };
  int tag_val = 0;
  if (parse_enum_required(obj, "type", biquad_combo_config_type_variants, ctx ? ctx : "biquad_combo_config", &tag_val, err) != 0) return -1;
  out->type = (biquad_combo_type_t)tag_val;

  switch (out->type) {
    case BIQUAD_COMBO_TYPE_BUTTERWORTH_HIGHPASS:
    case BIQUAD_COMBO_TYPE_BUTTERWORTH_LOWPASS:
    case BIQUAD_COMBO_TYPE_LINKWITZ_RILEY_HIGHPASS:
    case BIQUAD_COMBO_TYPE_LINKWITZ_RILEY_LOWPASS:
      {
        static const char *const req[] = {"freq", "order", NULL};
        if (require_json_fields(obj, req, ctx ? ctx : "biquad_combo_config", NULL, err) != 0) return -1;
        if (parse_json_double_strict(obj, "freq", ctx ? ctx : "biquad_combo_config", &out->freq, &out->has_freq, err) != 0) return -1;
        if (parse_json_int_strict(obj, "order", ctx ? ctx : "biquad_combo_config", &out->order, &out->has_order, err) != 0) return -1;
        break;
      }
    case BIQUAD_COMBO_TYPE_TILT:
      {
        if (parse_json_double_strict(obj, "gain", ctx ? ctx : "biquad_combo_config", &out->gain, &out->has_gain, err) != 0) return -1;
        if (parse_json_double_strict(obj, "high_gain", ctx ? ctx : "biquad_combo_config", &out->high_gain, &out->has_high_gain, err) != 0) return -1;
        if (parse_json_double_strict(obj, "freq", ctx ? ctx : "biquad_combo_config", &out->freq, &out->has_freq, err) != 0) return -1;
        break;
      }
    case BIQUAD_COMBO_TYPE_N_POINT_PEQ:
      {
        cJSON *arr_bands = cJSON_GetObjectItemCaseSensitive(obj, "bands");
        if (arr_bands) {
          if (!cJSON_IsArray(arr_bands)) {
            config_error_set(err, CONFIG_ERR_PARSE, "field '%s' in %s must be an array", "bands", ctx ? ctx : "biquad_combo_config");
            return -1;
          }
          int count = cJSON_GetArraySize(arr_bands);
          if (count > 0) {
            out->bands = (peq_band_t *)calloc(count, sizeof(peq_band_t));
            if (!out->bands) { config_error_set(err, CONFIG_ERR_PARSE, "Memory allocation failure"); return -1; }
            out->bands_count = count;
            for (int i = 0; i < count; i++) {
              cJSON *item = cJSON_GetArrayItem(arr_bands, i);
              if (parse_peq_band(item, "peq_band item", &out->bands[i], err) != 0) return -1;
            }
          }
        }
        break;
      }
    case BIQUAD_COMBO_TYPE_GRAPHIC_EQUALIZER:
      {
        if (parse_json_double_strict(obj, "freq_min", ctx ? ctx : "biquad_combo_config", &out->freq_min, &out->has_freq_min, err) != 0) return -1;
        if (parse_json_double_strict(obj, "freq_max", ctx ? ctx : "biquad_combo_config", &out->freq_max, &out->has_freq_max, err) != 0) return -1;
        cJSON *arr_gains = cJSON_GetObjectItemCaseSensitive(obj, "gains");
        if (arr_gains) {
          if (parse_double_array_strict(arr_gains, "gains", ctx ? ctx : "biquad_combo_config", &out->gains, &out->gains_count, err) != 0) return -1;
        }
        break;
      }
  }
  return 0;
}

cJSON *serialize_biquad_combo_config(const biquad_combo_config_t *in) {
  if (!in) return NULL;
  cJSON *obj = cJSON_CreateObject();
  if (!obj) return NULL;
  if (1) cJSON_AddStringToObject(obj, "type", biquad_combo_type_to_string(in->type));
  if (in->has_freq) cJSON_AddNumberToObject(obj, "freq", (double)in->freq);
  if (in->has_order) cJSON_AddNumberToObject(obj, "order", (double)in->order);
  if (in->has_gain) cJSON_AddNumberToObject(obj, "gain", (double)in->gain);
  if (in->has_high_gain) cJSON_AddNumberToObject(obj, "high_gain", (double)in->high_gain);
  if (in->bands && in->bands_count > 0) {
    cJSON *arr = cJSON_CreateArray();
    for (size_t i = 0; i < in->bands_count; i++) {
      cJSON_AddItemToArray(arr, serialize_peq_band(&in->bands[i]));
    }
    cJSON_AddItemToObject(obj, "bands", arr);
  }
  if (in->has_freq_min) cJSON_AddNumberToObject(obj, "freq_min", (double)in->freq_min);
  if (in->has_freq_max) cJSON_AddNumberToObject(obj, "freq_max", (double)in->freq_max);
  if (in->gains && in->gains_count > 0) {
    cJSON *arr = cJSON_CreateArray();
    for (size_t i = 0; i < in->gains_count; i++) {
      cJSON_AddItemToArray(arr, cJSON_CreateNumber((double)in->gains[i]));
    }
    cJSON_AddItemToObject(obj, "gains", arr);
  }
  return obj;
}

bool biquad_combo_config_equal(const biquad_combo_config_t *a, const biquad_combo_config_t *b) {
  if (a == b) return true;
  if (!a || !b) return false;
  if (a->type != b->type) return false;
  if (a->has_freq != b->has_freq) return false;
  if (a->has_freq) {
    if (a->freq != b->freq) return false;
  }
  if (a->has_order != b->has_order) return false;
  if (a->has_order) {
    if (a->order != b->order) return false;
  }
  if (a->has_gain != b->has_gain) return false;
  if (a->has_gain) {
    if (a->gain != b->gain) return false;
  }
  if (a->has_high_gain != b->has_high_gain) return false;
  if (a->has_high_gain) {
    if (a->high_gain != b->high_gain) return false;
  }
  if (a->bands_count != b->bands_count) return false;
  if (a->bands_count > 0) {
    if (!a->bands || !b->bands) return false;
    for (size_t i = 0; i < a->bands_count; i++) {
      if (!peq_band_equal(&a->bands[i], &b->bands[i])) return false;
    }
  }
  if (a->has_freq_min != b->has_freq_min) return false;
  if (a->has_freq_min) {
    if (a->freq_min != b->freq_min) return false;
  }
  if (a->has_freq_max != b->has_freq_max) return false;
  if (a->has_freq_max) {
    if (a->freq_max != b->freq_max) return false;
  }
  if (a->gains_count != b->gains_count) return false;
  if (a->gains_count > 0) {
    if (!a->gains || !b->gains) return false;
    for (size_t i = 0; i < a->gains_count; i++) {
      if (a->gains[i] != b->gains[i]) return false;
    }
  }
  return true;
}


