void filter_config_init(filter_config_t *out) {
  if (!out) return;
  memset(out, 0, sizeof(filter_config_t));
}

void free_filter_config_contents(filter_config_t *in) {
  if (!in) return;
  switch (in->type) {
    case FILTER_TYPE_GAIN: free_gain_config_contents(&in->parameters.gain); break;
    case FILTER_TYPE_VOLUME: free_volume_config_contents(&in->parameters.volume); break;
    case FILTER_TYPE_LOUDNESS: free_loudness_config_contents(&in->parameters.loudness); break;
    case FILTER_TYPE_BIQUAD: free_biquad_config_contents(&in->parameters.biquad); break;
    case FILTER_TYPE_CONV: free_conv_config_contents(&in->parameters.conv); break;
    case FILTER_TYPE_DELAY: free_delay_config_contents(&in->parameters.delay); break;
    case FILTER_TYPE_BIQUAD_COMBO: free_biquad_combo_config_contents(&in->parameters.biquad_combo); break;
    case FILTER_TYPE_DIFF_EQ: free_diff_eq_config_contents(&in->parameters.diff_eq); break;
    case FILTER_TYPE_DITHER: free_dither_config_contents(&in->parameters.dither); break;
    case FILTER_TYPE_CLIPPER: free_clipper_config_contents(&in->parameters.clipper); break;
    case FILTER_TYPE_LOOKAHEAD_LIMITER: free_lookahead_limiter_filter_config_contents(&in->parameters.lookahead_limiter); break;
    case FILTER_TYPE_INVALID: break;
  }
}

int parse_filter_config(const cJSON *obj, const char *ctx, filter_config_t *out, config_error_t *err) {
  if (!cJSON_IsObject(obj)) {
    config_error_set(err, CONFIG_ERR_PARSE, "%s must be an object", ctx ? ctx : "filter_config");
    return -1;
  }
  filter_config_init(out);

  static const config_enum_variant_t filter_type_variants[] = {
    {"Gain", FILTER_TYPE_GAIN},
    {"Volume", FILTER_TYPE_VOLUME},
    {"Loudness", FILTER_TYPE_LOUDNESS},
    {"Biquad", FILTER_TYPE_BIQUAD},
    {"Conv", FILTER_TYPE_CONV},
    {"Delay", FILTER_TYPE_DELAY},
    {"BiquadCombo", FILTER_TYPE_BIQUAD_COMBO},
    {"DiffEq", FILTER_TYPE_DIFF_EQ},
    {"Dither", FILTER_TYPE_DITHER},
    {"Clipper", FILTER_TYPE_CLIPPER},
    {"LookaheadLimiter", FILTER_TYPE_LOOKAHEAD_LIMITER},
    {NULL, 0}
  };
  const cJSON *tag_item = cJSON_GetObjectItemCaseSensitive(obj, "type");
  if (!tag_item || !cJSON_IsString(tag_item) || !tag_item->valuestring) {
    config_error_set(err, CONFIG_ERR_PARSE, "missing or non-string 'type' in %s", ctx ? ctx : "filter_config");
    return -1;
  }
  static const char *const allowed_container_keys[] = {"type", "parameters", "description", NULL};
  if (validate_unknown_fields(obj, allowed_container_keys, ctx ? ctx : "filter_config", err) != 0) return -1;
  int tag_val = 0;
  if (parse_enum_required(obj, "type", filter_type_variants, ctx ? ctx : "filter_config", &tag_val, err) != 0) return -1;
  out->type = (filter_type_t)tag_val;

  const cJSON *params_obj = cJSON_GetObjectItemCaseSensitive(obj, "parameters");
  if (!params_obj || !cJSON_IsObject(params_obj)) {
    config_error_set(err, CONFIG_ERR_PARSE, "missing 'parameters' in filter '%s'", ctx ? ctx : "filter_config");
    return -1;
  }

  switch (out->type) {
    case FILTER_TYPE_GAIN:
      if (parse_gain_config(params_obj, ctx ? ctx : "gain_config", &out->parameters.gain, err) != 0) return -1;
      break;
    case FILTER_TYPE_VOLUME:
      if (parse_volume_config(params_obj, ctx ? ctx : "volume_config", &out->parameters.volume, err) != 0) return -1;
      break;
    case FILTER_TYPE_LOUDNESS:
      if (parse_loudness_config(params_obj, ctx ? ctx : "loudness_config", &out->parameters.loudness, err) != 0) return -1;
      break;
    case FILTER_TYPE_BIQUAD:
      if (parse_biquad_config(params_obj, ctx ? ctx : "biquad_config", &out->parameters.biquad, err) != 0) return -1;
      break;
    case FILTER_TYPE_CONV:
      if (parse_conv_config(params_obj, ctx ? ctx : "conv_config", &out->parameters.conv, err) != 0) return -1;
      break;
    case FILTER_TYPE_DELAY:
      if (parse_delay_config(params_obj, ctx ? ctx : "delay_config", &out->parameters.delay, err) != 0) return -1;
      break;
    case FILTER_TYPE_BIQUAD_COMBO:
      if (parse_biquad_combo_config(params_obj, ctx ? ctx : "biquad_combo_config", &out->parameters.biquad_combo, err) != 0) return -1;
      break;
    case FILTER_TYPE_DIFF_EQ:
      if (parse_diff_eq_config(params_obj, ctx ? ctx : "diff_eq_config", &out->parameters.diff_eq, err) != 0) return -1;
      break;
    case FILTER_TYPE_DITHER:
      if (parse_dither_config(params_obj, ctx ? ctx : "dither_config", &out->parameters.dither, err) != 0) return -1;
      break;
    case FILTER_TYPE_CLIPPER:
      if (parse_clipper_config(params_obj, ctx ? ctx : "clipper_config", &out->parameters.clipper, err) != 0) return -1;
      break;
    case FILTER_TYPE_LOOKAHEAD_LIMITER:
      if (parse_lookahead_limiter_filter_config(params_obj, ctx ? ctx : "lookahead_limiter_filter_config", &out->parameters.lookahead_limiter, err) != 0) return -1;
      break;
    case FILTER_TYPE_INVALID: break;
  }
  return 0;
}

cJSON *serialize_filter_config(const filter_config_t *in) {
  if (!in) return NULL;
  cJSON *obj = cJSON_CreateObject();
  if (!obj) return NULL;
  cJSON_AddStringToObject(obj, "type", filter_type_to_string(in->type));
  switch (in->type) {
    case FILTER_TYPE_GAIN:
      cJSON_AddItemToObject(obj, "parameters", serialize_gain_config(&in->parameters.gain));
      break;
    case FILTER_TYPE_VOLUME:
      cJSON_AddItemToObject(obj, "parameters", serialize_volume_config(&in->parameters.volume));
      break;
    case FILTER_TYPE_LOUDNESS:
      cJSON_AddItemToObject(obj, "parameters", serialize_loudness_config(&in->parameters.loudness));
      break;
    case FILTER_TYPE_BIQUAD:
      cJSON_AddItemToObject(obj, "parameters", serialize_biquad_config(&in->parameters.biquad));
      break;
    case FILTER_TYPE_CONV:
      cJSON_AddItemToObject(obj, "parameters", serialize_conv_config(&in->parameters.conv));
      break;
    case FILTER_TYPE_DELAY:
      cJSON_AddItemToObject(obj, "parameters", serialize_delay_config(&in->parameters.delay));
      break;
    case FILTER_TYPE_BIQUAD_COMBO:
      cJSON_AddItemToObject(obj, "parameters", serialize_biquad_combo_config(&in->parameters.biquad_combo));
      break;
    case FILTER_TYPE_DIFF_EQ:
      cJSON_AddItemToObject(obj, "parameters", serialize_diff_eq_config(&in->parameters.diff_eq));
      break;
    case FILTER_TYPE_DITHER:
      cJSON_AddItemToObject(obj, "parameters", serialize_dither_config(&in->parameters.dither));
      break;
    case FILTER_TYPE_CLIPPER:
      cJSON_AddItemToObject(obj, "parameters", serialize_clipper_config(&in->parameters.clipper));
      break;
    case FILTER_TYPE_LOOKAHEAD_LIMITER:
      cJSON_AddItemToObject(obj, "parameters", serialize_lookahead_limiter_filter_config(&in->parameters.lookahead_limiter));
      break;
    case FILTER_TYPE_INVALID: break;
  }
  return obj;
}

bool filter_config_equal(const filter_config_t *a, const filter_config_t *b) {
  if (a == b) return true;
  if (!a || !b) return false;
  if (a->type != b->type) return false;
  switch (a->type) {
    case FILTER_TYPE_GAIN:
      return gain_config_equal(&a->parameters.gain, &b->parameters.gain);
    case FILTER_TYPE_VOLUME:
      return volume_config_equal(&a->parameters.volume, &b->parameters.volume);
    case FILTER_TYPE_LOUDNESS:
      return loudness_config_equal(&a->parameters.loudness, &b->parameters.loudness);
    case FILTER_TYPE_BIQUAD:
      return biquad_config_equal(&a->parameters.biquad, &b->parameters.biquad);
    case FILTER_TYPE_CONV:
      return conv_config_equal(&a->parameters.conv, &b->parameters.conv);
    case FILTER_TYPE_DELAY:
      return delay_config_equal(&a->parameters.delay, &b->parameters.delay);
    case FILTER_TYPE_BIQUAD_COMBO:
      return biquad_combo_config_equal(&a->parameters.biquad_combo, &b->parameters.biquad_combo);
    case FILTER_TYPE_DIFF_EQ:
      return diff_eq_config_equal(&a->parameters.diff_eq, &b->parameters.diff_eq);
    case FILTER_TYPE_DITHER:
      return dither_config_equal(&a->parameters.dither, &b->parameters.dither);
    case FILTER_TYPE_CLIPPER:
      return clipper_config_equal(&a->parameters.clipper, &b->parameters.clipper);
    case FILTER_TYPE_LOOKAHEAD_LIMITER:
      return lookahead_limiter_filter_config_equal(&a->parameters.lookahead_limiter, &b->parameters.lookahead_limiter);
    case FILTER_TYPE_INVALID: return false;
  }
  CDSP_UNREACHABLE();
  return false;
}


void pipeline_step_config_init(pipeline_step_config_t *out) {
  if (!out) return;
  memset(out, 0, sizeof(pipeline_step_config_t));
  out->bypassed = false;
}

void free_pipeline_step_config_contents(pipeline_step_config_t *in) {
  if (!in) return;
  if (in->channels) { free(in->channels); in->channels = NULL; in->channels_count = 0; }
  if (in->names) {
    for (size_t i = 0; i < in->names_count; i++) { free(in->names[i]); }
    free(in->names);
    in->names = NULL;
    in->names_count = 0;
  }
}

int parse_pipeline_step_config(const cJSON *obj, const char *ctx, pipeline_step_config_t *out, config_error_t *err) {
  if (!cJSON_IsObject(obj)) {
    config_error_set(err, CONFIG_ERR_PARSE, "%s must be an object", ctx ? ctx : "pipeline_step_config");
    return -1;
  }
  pipeline_step_config_init(out);

  static const config_enum_variant_t pipeline_step_config_type_variants[] = {
    {"Filter", PIPELINE_STEP_TYPE_FILTER},
    {"Mixer", PIPELINE_STEP_TYPE_MIXER},
    {"Processor", PIPELINE_STEP_TYPE_PROCESSOR},
    {NULL, 0}
  };
  int tag_val = 0;
  if (parse_enum_required(obj, "type", pipeline_step_config_type_variants, ctx ? ctx : "pipeline_step_config", &tag_val, err) != 0) return -1;
  out->type = (pipeline_step_type_t)tag_val;

  switch (out->type) {
    case PIPELINE_STEP_TYPE_FILTER:
      {
        static const char *const allowed[] = {"type", "names", "channels", "description", "bypassed", NULL};
        if (validate_unknown_fields(obj, allowed, ctx ? ctx : "pipeline_step_config", err) != 0) return -1;
        static const char *const req[] = {"names", NULL};
        if (require_json_fields(obj, req, ctx ? ctx : "pipeline_step_config", NULL, err) != 0) return -1;
        cJSON *arr_names = cJSON_GetObjectItemCaseSensitive(obj, "names");
        if (arr_names) {
          out->has_names = true;
          if (parse_labels_array_strict(arr_names, &out->names, &out->names_count, NULL) != 0) {
            config_error_set(err, CONFIG_ERR_PARSE, "field '%s' in %s must be an array of strings", "names", ctx ? ctx : "pipeline_step_config");
            return -1;
          }
        }
        cJSON *arr_channels = cJSON_GetObjectItemCaseSensitive(obj, "channels");
        if (arr_channels) {
          out->has_channels = true;
          if (parse_size_t_array_strict(arr_channels, "channels", ctx ? ctx : "pipeline_step_config", &out->channels, &out->channels_count, err) != 0) return -1;
        }
        if (parse_json_str_strict(obj, "description", ctx ? ctx : "pipeline_step_config", out->description, sizeof(out->description), NULL, err) != 0) return -1;
        if (parse_json_bool_strict(obj, "bypassed", ctx ? ctx : "pipeline_step_config", &out->bypassed, NULL, err) != 0) return -1;
        break;
      }
    case PIPELINE_STEP_TYPE_MIXER:
      {
        static const char *const allowed[] = {"type", "name", "description", "bypassed", NULL};
        if (validate_unknown_fields(obj, allowed, ctx ? ctx : "pipeline_step_config", err) != 0) return -1;
        static const char *const req[] = {"name", NULL};
        if (require_json_fields(obj, req, ctx ? ctx : "pipeline_step_config", NULL, err) != 0) return -1;
        if (parse_json_str_strict(obj, "name", ctx ? ctx : "pipeline_step_config", out->name, sizeof(out->name), &out->has_name, err) != 0) return -1;
        if (parse_json_str_strict(obj, "description", ctx ? ctx : "pipeline_step_config", out->description, sizeof(out->description), NULL, err) != 0) return -1;
        if (parse_json_bool_strict(obj, "bypassed", ctx ? ctx : "pipeline_step_config", &out->bypassed, NULL, err) != 0) return -1;
        break;
      }
    case PIPELINE_STEP_TYPE_PROCESSOR:
      {
        static const char *const allowed[] = {"type", "name", "description", "bypassed", NULL};
        if (validate_unknown_fields(obj, allowed, ctx ? ctx : "pipeline_step_config", err) != 0) return -1;
        static const char *const req[] = {"name", NULL};
        if (require_json_fields(obj, req, ctx ? ctx : "pipeline_step_config", NULL, err) != 0) return -1;
        if (parse_json_str_strict(obj, "name", ctx ? ctx : "pipeline_step_config", out->name, sizeof(out->name), &out->has_name, err) != 0) return -1;
        if (parse_json_str_strict(obj, "description", ctx ? ctx : "pipeline_step_config", out->description, sizeof(out->description), NULL, err) != 0) return -1;
        if (parse_json_bool_strict(obj, "bypassed", ctx ? ctx : "pipeline_step_config", &out->bypassed, NULL, err) != 0) return -1;
        break;
      }
  }
  return 0;
}

cJSON *serialize_pipeline_step_config(const pipeline_step_config_t *in) {
  if (!in) return NULL;
  cJSON *obj = cJSON_CreateObject();
  if (!obj) return NULL;
  if (1) cJSON_AddStringToObject(obj, "type", pipeline_step_type_to_string(in->type));
  if (1) if (in->description[0]) cJSON_AddStringToObject(obj, "description", in->description);
  if (in->has_channel) cJSON_AddNumberToObject(obj, "channel", (double)in->channel);
  if (in->channels && in->channels_count > 0) {
    cJSON *arr = cJSON_CreateArray();
    for (size_t i = 0; i < in->channels_count; i++) {
      cJSON_AddItemToArray(arr, cJSON_CreateNumber((double)in->channels[i]));
    }
    cJSON_AddItemToObject(obj, "channels", arr);
  }
  if (in->has_name) if (in->name[0]) cJSON_AddStringToObject(obj, "name", in->name);
  if (in->names && in->names_count > 0) {
    cJSON *arr = cJSON_CreateArray();
    for (size_t i = 0; i < in->names_count; i++) {
      cJSON_AddItemToArray(arr, in->names[i] ? cJSON_CreateString(in->names[i]) : cJSON_CreateNull());
    }
    cJSON_AddItemToObject(obj, "names", arr);
  }
  if (1) cJSON_AddBoolToObject(obj, "bypassed", in->bypassed);
  return obj;
}

bool pipeline_step_config_equal(const pipeline_step_config_t *a, const pipeline_step_config_t *b) {
  if (a == b) return true;
  if (!a || !b) return false;
  if (a->type != b->type) return false;
  if (strncmp(a->description, b->description, sizeof(a->description)) != 0) return false;
  if (a->has_channel != b->has_channel) return false;
  if (a->has_channel) {
    if (a->channel != b->channel) return false;
  }
  if (a->has_channels != b->has_channels) return false;
  if (a->has_channels) {
    if (a->channels_count != b->channels_count) return false;
    if (a->channels_count > 0) {
      if (!a->channels || !b->channels) return false;
      for (size_t i = 0; i < a->channels_count; i++) {
        if (a->channels[i] != b->channels[i]) return false;
      }
    }
  }
  if (a->has_name != b->has_name) return false;
  if (a->has_name) {
    if (strncmp(a->name, b->name, sizeof(a->name)) != 0) return false;
  }
  if (a->has_names != b->has_names) return false;
  if (a->has_names) {
    if (a->names_count != b->names_count) return false;
    if (a->names_count > 0) {
      if (!a->names || !b->names) return false;
      for (size_t i = 0; i < a->names_count; i++) {
        if ((a->names[i] == NULL) != (b->names[i] == NULL)) return false;
        if (a->names[i] && strcmp(a->names[i], b->names[i]) != 0) return false;
      }
    }
  }
  if (a->bypassed != b->bypassed) return false;
  return true;
}


